import 'package:flutter/material.dart'; import '../../services/api_service.dart';
class NotificationsScreen extends StatelessWidget { const NotificationsScreen({super.key}); @override Widget build(BuildContext context){final f=ApiService().notifications(); return Scaffold(appBar:AppBar(title:const Text('Notifications')),body:FutureBuilder<List<dynamic>>(future:f,builder:(c,s)=>!s.hasData?const Center(child:CircularProgressIndicator()):ListView(children:[for(final n in s.data!) ListTile(leading:Icon(n['is_read']==true?Icons.notifications_none:Icons.notifications_active),title:Text(n['title']),subtitle:Text(n['body']))])));}}
